examples_typescript:
// TypeScript example: streaming adapter that yields structured events and also exposes a legacy callback shim
import EventEmitter from 'events';

export type EventEnvelope = { type: string; seq: number; schema_version: 'v1'; payload: string | object }

export async function* invokeStreaming(prompt: string): AsyncIterable<EventEnvelope> {
  let seq = 0;
  // Simulated token streaming + a tool call event
  yield { type: 'token', seq: seq++, schema_version: 'v1', payload: 'Hello' }
  yield { type: 'token', seq: seq++, schema_version: 'v1', payload: ' world' }
  yield { type: 'tool_call', seq: seq++, schema_version: 'v1', payload: { name: 'search', args: { q: 'redwood runtime' } } }
  // tool result streamed in parts
  yield { type: 'tool_result', seq: seq++, schema_version: 'v1', payload: 'Search results part 1' }
  yield { type: 'tool_result', seq: seq++, schema_version: 'v1', payload: ' and part 2' }
  yield { type: 'done', seq: seq++, schema_version: 'v1', payload: { status: 'ok' } }
}

// Legacy shim: expose EventEmitter-based API for older clients
export function invokeWithEmitter(prompt: string): EventEmitter {
  const emitter = new EventEmitter();
  (async () => {
    try {
      for await (const ev of invokeStreaming(prompt)) {
        emitter.emit('event', ev);
      }
      emitter.emit('end');
    } catch (err) {
      emitter.emit('error', err);
    }
  })();
  return emitter;
}

// Usage: const e = invokeWithEmitter('...'); e.on('event', handle); e.on('end', cleanup);

examples_go:
// Go example: channel-based stream adapter and consumer
package sdkexamples

import (
  "context"
)

type EventEnvelope struct {
  Type string `json:\"type\"`
  Seq  int    `json:\"seq\"`
  SchemaVersion string `json:\"schema_version\"`
  Payload interface{} `json:\"payload\"`
}

func InvokeStreaming(ctx context.Context, prompt string) (<-chan EventEnvelope, <-chan error) {
  out := make(chan EventEnvelope)
  errc := make(chan error, 1)
  go func() {
    defer close(out)
    defer close(errc)
    seq := 0
    out <- EventEnvelope{Type: "token", Seq: seq, SchemaVersion: "v1", Payload: "Go hello"}; seq++
    out <- EventEnvelope{Type: "tool_call", Seq: seq, SchemaVersion: "v1", Payload: map[string]interface{}{"name": "calc", "args": map[string]interface{}{"op": "sum"}}}; seq++
    out <- EventEnvelope{Type: "tool_result", Seq: seq, SchemaVersion: "v1", Payload: "42"}; seq++
    out <- EventEnvelope{Type: "done", Seq: seq, SchemaVersion: "v1", Payload: map[string]interface{}{"status": "ok"}}
  }()
  return out, errc
}

